<script setup lang="ts">
import {ref,watch} from 'vue';import {apiError} from './apiError';
const props=defineProps<{projectId:string}>();
const criteria=ref<any[]>([]);const alternatives=ref<any[]>([]);const name=ref('经济—安全质效评价');const alpha=ref(.5);const history=ref<any[]>([]);const result=ref<any>(null);const busy=ref(false);const error=ref('');let token=0;
const checkNames=['电压稳定','频率稳定','黑启动可行性'];
const pptCriteria=[['n1','N-1通过率','benefit','比例'],['reliability','综合供电可靠率','benefit','比例'],['load_loss','多时间尺度失负荷比','cost','比例'],['island_hours','孤网稳定运行时长','benefit','h'],['voltage_margin','电压稳定裕度','benefit','pu'],['frequency_margin','频率稳定裕度','benefit','Hz'],['restoration','黑启动总恢复时间','cost','min'],['payback','投资回报期','cost','年'],['benefit_cost','收益与成本比','benefit','比值'],['expected_loss','极端事件期望损失','cost','元']];
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
function nextId(prefix:string,rows:any[]){let n=1;while(rows.some(r=>r.id===prefix+n))n++;return prefix+n}
function addCriterion(){criteria.value.push({id:nextId('指标',criteria.value),name:'新指标',direction:'benefit',unit:'',safety_limit:null});for(const a of alternatives.value)a.values.push(null)}
function removeCriterion(index:number){criteria.value.splice(index,1);for(const a of alternatives.value)a.values.splice(index,1)}
function loadPpt(){criteria.value=pptCriteria.map(([id,name,direction,unit])=>({id,name,direction,unit,safety_limit:null}));for(const a of alternatives.value)a.values=criteria.value.map(()=>null);result.value=null}
function addAlternative(){const id=nextId('方案',alternatives.value);alternatives.value.push({id,name:id,values:criteria.value.map(()=>null),provenance:'',source_run_id:null,checks:checkNames.map(name=>({name,status:'not_checked',evidence:''}))})}
watch(()=>props.projectId,async()=>{const request=++token;busy.value=false;result.value=null;history.value=[];error.value='';loadPpt();alternatives.value=[];addAlternative();addAlternative();if(!props.projectId)return;try{const rows=await api('/api/effect-evaluations?project_id='+props.projectId);if(request===token)history.value=rows}catch(e){if(request===token)error.value=String(e)}},{immediate:true});
async function calculate(){const request=token,id=props.projectId;busy.value=true;error.value='';result.value=null;try{for(const a of alternatives.value)for(let j=0;j<criteria.value.length;j++)if(a.values[j]===null||a.values[j]===''||!Number.isFinite(Number(a.values[j])))throw Error(a.name+'：请填写'+criteria.value[j].name+'的有效数值');const project=await api('/api/projects/'+id);if(request!==token)return;const body={project_id:id,project_revision:project.revision,name:name.value,criteria:criteria.value.map(c=>({...c,safety_limit:c.safety_limit===''?null:c.safety_limit})),alternatives:alternatives.value,entropy_share:alpha.value,required_checks:checkNames};const d=await api('/api/effect-evaluations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(request!==token)return;result.value=d;const records=await api('/api/effect-evaluations?project_id='+id);if(request===token)history.value=records}catch(e){if(request===token)error.value=String(e)}finally{if(request===token)busy.value=false}}
async function inspect(id:string){const request=token;try{const d=await api('/api/effect-evaluations/'+id);if(request===token&&d.project_id===props.projectId)result.value=d}catch(e){if(request===token)error.value=String(e)}}
function download(){const u=URL.createObjectURL(new Blob([JSON.stringify(result.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='质效评价-'+result.value.id.slice(0,8)+'.json';a.click();URL.revokeObjectURL(u)}
const statusNames:Record<string,string>={failed:'硬约束或校核未通过',not_checked:'仍有必要项目未校核',passed_as_supplied:'按所提供依据通过（未独立验证）'};
</script>
<template><article><h3>经济—安全质效评价 · 熵权-CRITIC-TOPSIS</h3><p>依据完整中期PPT第54—57页，采用极值标准化、熵权与CRITIC组合赋权和TOPSIS。请输入实际计算/实测指标和来源；此页面不会自动补造动态稳定、恢复及全寿命经济指标。</p><p v-if="error" class="error">{{error}}</p><div class="actions"><label>评价名称 <input v-model="name"></label><label>熵权占比α <input type="number" min="0" max="1" step="0.1" v-model.number="alpha"></label><button @click="loadPpt" :disabled="busy">重建PPT指标体系</button><button @click="addCriterion" :disabled="busy||criteria.length>=30">新增指标</button></div><p>组合权重=α×熵权+(1-α)×CRITIC；PPT未给固定组合比例，α作为本次研究假设保存。硬阈值：效益型须≥阈值，成本型须≤阈值；留空表示未设置该项门槛。</p><div class="scroll"><table><tr><th>指标编号</th><th>指标名称</th><th>方向</th><th>单位</th><th>硬阈值</th><th></th></tr><tr v-for="(c,j) in criteria" :key="j"><td><input v-model="c.id"></td><td><input v-model="c.name"></td><td><select v-model="c.direction"><option value="benefit">效益（越大越好）</option><option value="cost">成本（越小越好）</option></select></td><td><input v-model="c.unit"></td><td><input type="number" step="any" v-model.number="c.safety_limit"></td><td><button @click="removeCriterion(j)" :disabled="busy||criteria.length<=1">删除</button></td></tr></table></div>
<h3>方案指标矩阵</h3><p>每项都须有数值，缺测请先补数据或删除该评价指标，不能以0替代未知值。数学排序与安全可行性独立显示。</p><div class="scroll"><table><tr><th>编号</th><th>名称</th><th v-for="c in criteria" :key="c.id">{{c.name}} / {{c.unit}}</th><th>数据来源与口径</th><th>关联计算ID（可选）</th><th></th></tr><tr v-for="(a,i) in alternatives" :key="i"><td><input v-model="a.id"></td><td><input v-model="a.name"></td><td v-for="(_,j) in criteria" :key="j"><input type="number" step="any" :aria-label="a.name+' '+criteria[j].name" v-model.number="a.values[j]"></td><td><input v-model="a.provenance" :aria-label="a.name+' 数据来源'"></td><td><input :value="a.source_run_id" @input="a.source_run_id=($event.target as HTMLInputElement).value||null"></td><td><button @click="alternatives.splice(i,1)" :disabled="busy||alternatives.length<=2">删除</button></td></tr></table></div><button @click="addAlternative" :disabled="busy||alternatives.length>=100">新增方案</button>
<details><summary>必要安全校核与依据</summary><p>没有校核证据保持“未校核”。即便录入通过，也仅保存为外部提供依据，不能代替平台独立动态验证。</p><div v-for="a in alternatives" :key="a.id"><h4>{{a.name}}</h4><label v-for="c in a.checks" :key="c.name">{{c.name}} <select v-model="c.status"><option value="not_checked">未校核</option><option value="passed">依据显示通过</option><option value="failed">未通过</option></select><input v-model="c.evidence" placeholder="校核模型/报告与具体结论"></label></div></details><button class="primary" @click="calculate" :disabled="busy||!projectId">{{busy?'计算中…':'计算并归档质效评价'}}</button>
<template v-if="result"><h3>归档评价结果 · {{result.input.name}}</h3><p>以下结果来自编号 {{result.id.slice(0,8)}} 的冻结输入，当前编辑不会改变已归档结果；修改后需重新计算。</p><table><tr><th>数学排名</th><th>方案</th><th>贴近度</th><th>距正理想解</th><th>距负理想解</th><th>约束状态</th></tr><tr v-for="r in result.result.ranking" :key="r.id"><td>{{r.rank}}</td><td>{{r.name}}</td><td>{{r.score.toFixed(6)}}</td><td>{{r.distance_to_ideal.toFixed(6)}}</td><td>{{r.distance_to_anti_ideal.toFixed(6)}}</td><td>{{statusNames[r.gate]}}</td></tr></table><p v-for="note in result.result.notes">{{note}}</p><h4>指标权重</h4><table><tr><th>指标</th><th>熵权</th><th>CRITIC</th><th>组合权重</th><th>信息性</th></tr><tr v-for="w in result.result.weights"><td>{{w.name}}</td><td>{{w.entropy.toFixed(6)}}</td><td>{{w.critic.toFixed(6)}}</td><td>{{w.combined.toFixed(6)}}</td><td>{{w.active?'有效':'常量，未计权重'}}</td></tr></table><button @click="download">导出完整评价JSON</button><details><summary>标准化矩阵、阈值与校核证据</summary><pre>{{JSON.stringify(result,null,2)}}</pre></details></template><h3>本工程评价档案</h3><button v-for="h in history" :key="h.id" @click="inspect(h.id)" class="record">{{h.created}} · {{h.name}}</button></article></template>
<style scoped>input,select{padding:8px;border:1px solid #c8dcdf;max-width:100%}.actions{display:flex;gap:14px;flex-wrap:wrap;margin:16px 0}.actions input{width:200px}.scroll{overflow:auto;max-height:420px;margin:18px 0}td input{width:145px}th{white-space:nowrap;position:sticky;top:0}details{margin:20px 0}summary{cursor:pointer}details label{display:flex;gap:12px;align-items:center;margin:8px 0}details input{width:500px}.primary{margin:20px 0}.record{display:block;margin:8px 0}pre{max-height:500px;overflow:auto;white-space:pre-wrap}</style>
